// Renderer-agnostic presentation state. Never owns electrical state or authorises data access.
export function mountApplicationShell(root,{id='forge',context={},views=[],commands=[],browser=[],properties=null,status=null,help=null,links=[],drawers={},onView=()=>{}}={}){
 const doc=root.ownerDocument,e=(tag,text,className)=>{const n=doc.createElement(tag);if(text!=null)n.textContent=text;if(className)n.className=className;return n;};
 const node=e('section',null,'forge-app-shell');node.dataset.forgeShell=id;node.setAttribute('aria-label','Forge application');
 const appbar=e('header',null,'forge-shell-appbar'),brand=e('strong','FORGE'),identity=e('span',null,'forge-shell-identity'),revision=e('span'),save=e('span');save.setAttribute('aria-live','polite');appbar.append(brand,identity,revision,save);
 for(const {text,href} of links){const a=e('a',text);a.href=href;appbar.append(a);}
 const commandbar=e('nav',null,'forge-shell-commands');commandbar.setAttribute('aria-label','Forge commands');const groups=new Map();
 for(const name of ['Design','Analyse','Build','Document']){const d=e('details'),s=e('summary',name),body=e('div');body.className='forge-shell-menu';d.append(s,body);commandbar.append(d);groups.set(name,{d,body});d.addEventListener('toggle',()=>{if(d.open)for(const x of groups.values())if(x.d!==d)x.d.open=false;});}
 const grid=e('div',null,'forge-shell-grid'),nav=e('aside',null,'forge-shell-browser'),work=e('section',null,'forge-shell-workspace'),props=properties||e('aside'),statusbar=e('footer',null,'forge-shell-status');props.classList.add('forge-shell-properties');
 nav.setAttribute('aria-label','Project and design browser');props.setAttribute('aria-label','Properties');const navHeading=e('h2','Browser'),navItems=e('nav');navItems.setAttribute('aria-label','Forge browser');nav.append(navHeading,navItems);
 const workTitle=e('h2','Workspace'),tabs=e('nav',null,'forge-shell-views'),content=e('div',null,'forge-shell-content');workTitle.tabIndex=-1;tabs.setAttribute('aria-label','Workspace views');work.append(workTitle,tabs,content);grid.append(nav,work,props);
 const state={view:null,browser:null,selection:null,context:{},compact:false},registry=new Map(),tabButtons=new Map(),browserButtons=new Map(),homes={},panelNodes={browser:nav,properties:props},panels={};
 let opener=null;
 function button(parent,text,run){const b=e('button',text);b.type='button';b.addEventListener('click',run);parent.append(b);return b;}
 function closeMenus(restore=false){for(const {d} of groups.values())if(d.open){d.open=false;if(restore)d.querySelector('summary').focus();}}
 function selectView(name,{focus=false}={}){const v=registry.get(name);if(!v||v.disabled)return false;state.view=name;for(const [key,value] of registry)value.node.hidden=key!==name;for(const [key,b] of tabButtons)b.setAttribute('aria-pressed',String(key===name));workTitle.textContent=v.title;node.dataset.activeView=name;onView(name);if(focus)workTitle.focus({preventScroll:true});return true;}
 function setContext(value){state.context={...state.context,...value};identity.textContent=state.context.title||'Local design';revision.textContent=state.context.revision||'';save.textContent=state.context.save||'Unsaved local design';node.dataset.context=state.context.kind||'local';}
 function closePanel(name,restore=true){const d=panels[name];if(d?.open)d.close();toggleButtons[name]?.setAttribute('aria-expanded','false');if(!state.compact)panelNodes[name].hidden=true;if(restore)(opener?.isConnected?opener:toggleButtons[name])?.focus({preventScroll:true});}
 function openPanel(name){const p=panelNodes[name];opener=doc.activeElement;if(state.compact){for(const key of Object.keys(panels))if(key!==name&&panels[key].open)closePanel(key,false);const d=panels[name];if(!d.open)d.showModal();d.querySelector('button').focus({preventScroll:true});}else{p.hidden=false;p.querySelector('button,input,select,summary,[tabindex]')?.focus({preventScroll:true});}toggleButtons[name].setAttribute('aria-expanded','true');}
 const toggleButtons={};for(const [name,title] of [['browser','Browser'],['properties','Properties']]){const b=button(commandbar,title,()=>{if(state.compact?panels[name].open:!panelNodes[name].hidden)closePanel(name);else openPanel(name);});b.setAttribute('aria-controls',id+'-'+name+'-panel');b.setAttribute('aria-expanded','true');toggleButtons[name]=b;panelNodes[name].id=id+'-'+name+'-panel';
  const existing=drawers[name],d=existing||e('dialog',null,'forge-shell-drawer'),body=existing?.querySelector('.forge-sheet-body')||e('div',null,'forge-shell-drawer-body');
  if(!existing){const bar=e('div',null,'forge-shell-drawer-bar');bar.append(e('h2',title));button(bar,'Close '+title,()=>closePanel(name));d.append(bar,body);root.append(d);}else{for(const close of d.querySelectorAll('[data-mobile-close]'))close.addEventListener('click',()=>closePanel(name));}
  d.dataset.shellDrawer=name;d.addEventListener('cancel',event=>{event.preventDefault();closePanel(name);});panels[name]=d;homes[name]=doc.createComment(name+' shell position');panelNodes[name].before(homes[name]);
 }
 for(const v of views){registry.set(v.id,v);v.node.dataset.shellView=v.id;content.append(v.node);const b=button(tabs,v.title,()=>{closeMenus();selectView(v.id,{focus:true});});b.disabled=!!v.disabled;b.setAttribute('aria-controls',id+'-view-'+v.id);v.node.id=v.node.id||id+'-view-'+v.id; // Existing controller IDs remain authoritative.
  b.setAttribute('aria-controls',v.node.id);if(v.reason)b.setAttribute('aria-description',v.reason);tabButtons.set(v.id,b);}
 function selectBrowser(item,{focus=true}={}){state.browser=item.id;for(const [key,b] of browserButtons)b.setAttribute('aria-current',key===item.id?'true':'false');item.run?.();if(item.view)selectView(item.view);if(item.properties)openPanel('properties');else if(focus)workTitle.focus({preventScroll:true});if(state.compact&&panels.browser.open)closePanel('browser',false);}
 for(const item of browser){const b=button(navItems,item.title,()=>selectBrowser(item));b.dataset.browserItem=item.id;browserButtons.set(item.id,b);}
 for(const c of commands){const group=groups.get(c.group);if(!group)throw Error('Unknown command group '+c.group);let n=c.node;if(n)group.body.append(n);else if(c.href){n=e('a',c.title);n.href=c.href;group.body.append(n);}else n=button(group.body,c.title,()=>{closeMenus();if(c.view)selectView(c.view,{focus:true});c.run?.();});n.addEventListener('click',()=>closeMenus());n.dataset.shellCommand=c.id||c.title;n.disabled=!!c.disabled;if(c.reason)n.setAttribute('aria-description',c.reason);}
 for(const {body} of groups.values())if(!body.children.length)body.append(e('p','Commands appear here when available for the current project or view.'));
 if(status)statusbar.append(status);statusbar.append(e('span','Physical fit: UNKNOWN'));if(help){const helpDialog=e('dialog',null,'forge-shell-help');helpDialog.setAttribute('aria-label','Learn Forge');const close=button(helpDialog,'Close Help',()=>{helpDialog.close();helpButton.focus();});helpDialog.append(help);const helpButton=button(commandbar,'Help / Learn Forge',()=>{closeMenus();helpDialog.showModal();close.focus();});helpDialog.addEventListener('cancel',event=>{event.preventDefault();helpDialog.close();helpButton.focus();});node.append(helpDialog);}
 node.prepend(appbar,commandbar,grid,statusbar);root.append(node);
 const media=doc.defaultView.matchMedia('(max-width: 1100px)');function layout(){state.compact=media.matches;node.dataset.compact=String(state.compact);for(const name of Object.keys(panelNodes)){if(panels[name].open)closePanel(name,false);panelNodes[name].hidden=false;if(state.compact)(panels[name].querySelector('.forge-sheet-body,.forge-shell-drawer-body')).append(panelNodes[name]);else homes[name].after(panelNodes[name]);toggleButtons[name].setAttribute('aria-expanded',String(!state.compact));}}
 const keydown=event=>{if(event.key==='Escape')closeMenus(true);};node.addEventListener('keydown',keydown);media.addEventListener('change',layout);setContext(context);layout();if(views.length)selectView(views.find(v=>!v.disabled)?.id);
 return {node,appbar,workspace:work,properties:props,browser:nav,commands:groups,status:statusbar,state,selectView,setContext,selectBrowser,openPanel,closePanel,panels,setSelection(value){state.selection=value;node.dataset.selection=value?.kind||'none';},focusWorkspace(){workTitle.focus({preventScroll:true});},destroy(){for(const p of Object.values(panels))if(p.open)p.close();media.removeEventListener('change',layout);node.removeEventListener('keydown',keydown);node.remove();for(const p of Object.values(panels))if(!Object.values(drawers).includes(p))p.remove();}};
}
